        encoded_marks.append({
            "name": observed.name, "args": encoded_args, "kwargs": value_record(observed.kwargs),
        })
    return {
        "parameters": {
            "type": "dict", "items": [
                [key, enum_record(value) if key == "health" else value_record(value)]
                for key, value in parameters.items()
            ],
